});

test("a model request is recorded BEFORE it leaves, graded, and closed when it answers", () => {
  const o = createOutbound({ storage: store(), now: () => "T" });
  const h = o.sendModel({ auditId: "a1", model: "openai-fast", messages: msgs, run: "r1" });
