  const msgs = body.messages.filter((m) => m.role !== "system").map((m) => ({ role: m.role, content: m.content }));
  const out = { model: MODEL, max_tokens: Math.min(body.max_tokens || 300, 300), messages: msgs, ...(sys ? { system: sys } : {}) };
