const leaked = (s) => PLANTED.filter((p) => s.toLowerCase().includes(p.toLowerCase()));

const taint = createTaint(); taint.add("/Users/eleanor/cases/kettering-clinic", "folder path");
const ledger = createOutbound({ storage: store(), taint });
