export function unsourcedPlan(_policy = UNSOURCED_ANSWERS, { live = false } = {}) {
  return { callModel: false, sourceBlock: null, standing: null, gap: live ? "live" : "unreached", policy: UNSOURCED_ANSWERS };
}

